  const me = await (await page.request.get("/api/v1/auth/me")).json();
  await page.request.patch(`/api/v1/seats/${id}`, {
    headers: { "X-CSRF-Token": me.csrfToken },
    data: { x: at.x, y: at.y },
  });
};

