/** 사용할 수 없는 좌석. type과 status 어느 쪽으로도 지정될 수 있다. */
export const seatUnavailable = (seat: Seat) =>
  seat.type === "unavailable" || seat.status === "unavailable";

export const seatColor = (seat: Seat) =>
  seatUnavailable(seat)
    ? "#8796A1"
